package com.tcurrent.liverightnow;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import javax.inject.Inject;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.inject.Provides;
import com.tcurrent.liverightnow.model.Platform;
import com.tcurrent.liverightnow.model.StreamInfo;
import com.tcurrent.liverightnow.notification.StreamNotificationManager;
import com.tcurrent.liverightnow.oauth.KickOAuthManager;
import com.tcurrent.liverightnow.oauth.OAuthLoopbackServer;
import com.tcurrent.liverightnow.oauth.TwitchOAuthManager;
import com.tcurrent.liverightnow.service.KickService;
import com.tcurrent.liverightnow.service.TwitchService;
import com.tcurrent.liverightnow.ui.LiveRightNowPanel;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
    name = "Live Right Now",
    description = "Tracks specific Twitch and Kick streamers and alerts when they go live",
    tags = {"live", "activity", "tracker", "twitch", "kick", "stream", "notifications"}
)
public class LiveRightNowPlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(LiveRightNowPlugin.class);

    @Inject
    private Client client;

    @Inject
    private LiveRightNowConfig config;

    @Inject
    private TwitchService twitchService;

    @Inject
    private KickService kickService;

    @Inject
    private TwitchOAuthManager twitchOAuthManager;

    @Inject
    private KickOAuthManager kickOAuthManager;

    @Inject
    private OAuthLoopbackServer loopbackServer;

    @Inject
    private StreamNotificationManager notificationManager;

    @Inject
    private ScheduledExecutorService executorService;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private LiveRightNowPanel panel;

    private static final int POLLING_INTERVAL_MINUTES = 2;

    private NavigationButton navButton;
    private final Map<String, Boolean> liveStateCache = new ConcurrentHashMap<>();
    private ScheduledFuture<?> pollingTask;
    private boolean initialized = false;
    private boolean loginReminderSent = false;

    @Provides
    LiveRightNowConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(LiveRightNowConfig.class);
    }

    @Override
    protected void startUp()
    {
        migrateTwitchClientId();
        liveStateCache.clear();
        initialized = false;
        loginReminderSent = false;

        BufferedImage icon = createPluginIcon();
        navButton = NavigationButton.builder()
            .tooltip("Live Right Now")
            .icon(icon)
            .priority(7)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navButton);
        panel.refreshAccountsUi();

        if (client.getGameState() == GameState.LOGGED_IN)
        {
            checkAndSendConnectReminder();
            executorService.execute(this::checkStreams);
        }

        startPolling();
    }

    private void migrateTwitchClientId()
    {
        String configuredClientId = config.twitchClientId();
        if (configuredClientId == null || configuredClientId.isBlank() ||
            "kimne78kx3ncx6brgo4mv6wki5h1ko".equals(configuredClientId) ||
            "ka3clhecbpbyijmalu7th9rkfuol9f".equals(configuredClientId))
        {
            configManager.setConfiguration(
                LiveRightNowConfig.GROUP,
                LiveRightNowConfig.TWITCH_CLIENT_ID_KEY,
                LiveRightNowConfig.TWITCH_DEFAULT_CLIENT_ID
            );
        }
    }

    @Override
    protected void shutDown()
    {
        stopPolling();
        loopbackServer.stop();
        clientToolbar.removeNavigation(navButton);
        liveStateCache.clear();
        initialized = false;
        loginReminderSent = false;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            checkAndSendConnectReminder();
            executorService.execute(this::checkStreams);
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            loginReminderSent = false;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!LiveRightNowConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        if (LiveRightNowConfig.TWITCH_OAUTH_TOKEN_KEY.equals(event.getKey()) ||
            LiveRightNowConfig.TWITCH_CONNECTED_USER_KEY.equals(event.getKey()) ||
            LiveRightNowConfig.KICK_OAUTH_TOKEN_KEY.equals(event.getKey()) ||
            LiveRightNowConfig.KICK_CONNECTED_USER_KEY.equals(event.getKey()))
        {
            if (LiveRightNowConfig.TWITCH_OAUTH_TOKEN_KEY.equals(event.getKey()))
            {
                twitchOAuthManager.handleConfigurationReset();
            }
            else if (LiveRightNowConfig.KICK_OAUTH_TOKEN_KEY.equals(event.getKey()))
            {
                kickOAuthManager.handleConfigurationReset();
            }
            panel.refreshAccountsUi();
            executorService.execute(this::checkStreams);
        }
        else if (LiveRightNowConfig.TWITCH_STREAMERS_KEY.equals(event.getKey()) ||
                 LiveRightNowConfig.KICK_STREAMERS_KEY.equals(event.getKey()))
        {
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                checkAndSendConnectReminder();
            }
            executorService.execute(this::checkStreams);
        }
    }

    private synchronized void startPolling()
    {
        if (pollingTask != null && !pollingTask.isCancelled())
        {
            pollingTask.cancel(true);
        }

        pollingTask = executorService.scheduleWithFixedDelay(
            this::checkStreams,
            0,
            POLLING_INTERVAL_MINUTES,
            TimeUnit.MINUTES
        );
    }

    private synchronized void stopPolling()
    {
        if (pollingTask != null)
        {
            pollingTask.cancel(true);
            pollingTask = null;
        }
    }

    private void checkStreams()
    {
        try
        {
            if (client.getGameState() != GameState.LOGGED_IN)
            {
                return;
            }

            boolean twitchConnected = twitchOAuthManager.isConnected();
            boolean kickConnected = kickOAuthManager.isConnected();

            if (!twitchConnected && !kickConnected)
            {
                panel.updateStreams(Collections.emptyList());
                return;
            }

            List<StreamInfo> activeStreams = new ArrayList<>();
            List<StreamInfo> newSessions = new ArrayList<>();

            if (twitchConnected)
            {
                List<String> twitchChannels = parseChannelList(config.twitchStreamers());
                if (!twitchChannels.isEmpty())
                {
                    List<StreamInfo> twitchStreams = twitchService.fetchStreams(twitchChannels);
                    newSessions.addAll(processStreamUpdates(twitchStreams));
                    for (StreamInfo s : twitchStreams)
                    {
                        if (s.isLive())
                        {
                            activeStreams.add(s);
                        }
                    }
                }
            }

            if (kickConnected)
            {
                List<String> kickChannels = parseChannelList(config.kickStreamers());
                if (!kickChannels.isEmpty())
                {
                    List<StreamInfo> kickStreams = kickService.fetchStreams(kickChannels);
                    newSessions.addAll(processStreamUpdates(kickStreams));
                    for (StreamInfo s : kickStreams)
                    {
                        if (s.isLive())
                        {
                            activeStreams.add(s);
                        }
                    }
                }
            }

            // Notified once across both platforms so a streamer live on Twitch and Kick
            // simultaneously gets a single combined message instead of two separate ones.
            notificationManager.notifyStreamersLive(newSessions);

            panel.updateStreams(activeStreams);

            if (!initialized)
            {
                initialized = true;
            }
        }
        catch (Exception e)
        {
            log.error("Error during stream status polling", e);
        }
    }

    private List<StreamInfo> processStreamUpdates(List<StreamInfo> streams)
    {
        List<StreamInfo> newSessions = new ArrayList<>();
        Map<String, String> pendingSessions = new HashMap<>();
        for (StreamInfo stream : streams)
        {
            String key = makeCacheKey(stream.getPlatform(), stream.getChannelName());
            boolean wasLive = liveStateCache.getOrDefault(key, false);
            boolean isLiveNow = stream.isLive();

            if (isLiveNow)
            {
                String sessionId = stream.getSessionId().trim();
                boolean newSession;
                if (!sessionId.isEmpty())
                {
                    // wasLive gates re-notification within this run (e.g. after a config reset
                    // clears notifiedSessions); the persisted value gates it across restarts.
                    String notifiedSession = getNotifiedSession(key);
                    newSession = !wasLive && !sessionId.equals(notifiedSession);
                }
                else
                {
                    newSession = initialized && !wasLive;
                }

                if (newSession)
                {
                    newSessions.add(stream);
                    pendingSessions.put(key, sessionId);
                }
                liveStateCache.put(key, true);
            }
            else if (!isLiveNow && wasLive)
            {
                liveStateCache.put(key, false);
            }
            else if (!liveStateCache.containsKey(key))
            {
                liveStateCache.put(key, isLiveNow);
            }
        }

        for (Map.Entry<String, String> pendingSession : pendingSessions.entrySet())
        {
            if (!pendingSession.getValue().isEmpty())
            {
                saveNotifiedSession(pendingSession.getKey(), pendingSession.getValue());
            }
        }

        return newSessions;
    }

    private String makeCacheKey(Platform platform, String channelName)
    {
        return platform.name() + ":" + channelName.toLowerCase();
    }

    private String getNotifiedSession(String key)
    {
        String history = configManager.getConfiguration(
            LiveRightNowConfig.GROUP,
            LiveRightNowConfig.NOTIFIED_SESSIONS_KEY
        );
        if (history == null || history.isEmpty())
        {
            return null;
        }

        for (String entry : history.split("\\n"))
        {
            String prefix = key + "=";
            if (entry.startsWith(prefix))
            {
                return entry.substring(prefix.length());
            }
        }
        return null;
    }

    private void saveNotifiedSession(String key, String sessionId)
    {
        String history = configManager.getConfiguration(
            LiveRightNowConfig.GROUP,
            LiveRightNowConfig.NOTIFIED_SESSIONS_KEY
        );
        String prefix = key + "=";
        StringBuilder updated = new StringBuilder();
        boolean replaced = false;

        if (history != null && !history.isEmpty())
        {
            for (String entry : history.split("\\n"))
            {
                if (entry.isEmpty())
                {
                    continue;
                }
                if (entry.startsWith(prefix))
                {
                    entry = prefix + sessionId;
                    replaced = true;
                }
                if (updated.length() > 0)
                {
                    updated.append('\n');
                }
                updated.append(entry);
            }
        }

        if (!replaced)
        {
            if (updated.length() > 0)
            {
                updated.append('\n');
            }
            updated.append(prefix).append(sessionId);
        }

        configManager.setConfiguration(
            LiveRightNowConfig.GROUP,
            LiveRightNowConfig.NOTIFIED_SESSIONS_KEY,
            updated.toString()
        );
    }

    static List<String> parseChannelList(String raw)
    {
        if (raw == null || raw.trim().isEmpty())
        {
            return Collections.emptyList();
        }

        Map<String, String> seen = new java.util.LinkedHashMap<>();
        for (String item : raw.split("[,\\n\\r]+"))
        {
            String trimmed = item.trim();
            if (!trimmed.isEmpty())
            {
                seen.putIfAbsent(trimmed.toLowerCase(), trimmed);
            }
        }

        return new ArrayList<>(seen.values());
    }

    private void checkAndSendConnectReminder()
    {
        boolean hasTwitchStreamers = !parseChannelList(config.twitchStreamers()).isEmpty();
        boolean twitchConnected = twitchOAuthManager.isConnected();
        boolean hasKickStreamers = !parseChannelList(config.kickStreamers()).isEmpty();
        boolean kickConnected = kickOAuthManager.isConnected();

        boolean needsTwitch = hasTwitchStreamers && !twitchConnected;
        boolean needsKick = hasKickStreamers && !kickConnected;

        if (needsTwitch || needsKick)
        {
            if (!loginReminderSent)
            {
                loginReminderSent = true;
                String msg;
                if (needsTwitch && needsKick)
                {
                    msg = "Connect your Twitch and Kick accounts in the side panel to get started with stream notifications.";
                }
                else if (needsTwitch)
                {
                    msg = "Connect your Twitch account in the side panel to get started with stream notifications.";
                }
                else
                {
                    msg = "Connect your Kick account in the side panel to get started with stream notifications.";
                }
                notificationManager.notifyConnectReminder(msg);
            }
        }
    }

    private BufferedImage createPluginIcon()
    {
        BufferedImage resourceIcon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
        if (resourceIcon != null)
        {
            return resourceIcon;
        }

        int size = 16;
        BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // Top-left Twitch half
        java.awt.Polygon twitchPoly = new java.awt.Polygon(new int[]{0, size, 0}, new int[]{0, 0, size}, 3);
        g.setClip(twitchPoly);
        g.setColor(new Color(145, 70, 255));
        g.fillRect(0, 0, size, size);

        // Bottom-right Kick half
        java.awt.Polygon kickPoly = new java.awt.Polygon(new int[]{size, size, 0}, new int[]{0, size, size}, 3);
        g.setClip(kickPoly);
        g.setColor(new Color(18, 18, 18));
        g.fillRect(0, 0, size, size);

        // Kick Green K letter mark
        g.setColor(new Color(83, 252, 24));
        g.fillRect(8, 6, 2, 8);

        // Diagonal divider
        g.setClip(null);
        g.setColor(new Color(0, 0, 0, 180));
        g.drawLine(size, 0, 0, size);

        g.dispose();
        return image;
    }
}

package com.tcurrent.liverightnow.model;

public enum Platform
{
    TWITCH("Twitch", "https://twitch.tv/"),
    KICK("Kick", "https://kick.com/");

    private final String displayName;
    private final String baseUrl;

    Platform(String displayName, String baseUrl)
    {
        this.displayName = displayName;
        this.baseUrl = baseUrl;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public String getBaseUrl()
    {
        return baseUrl;
    }

    public String getChannelUrl(String username)
    {
        return baseUrl + username;
    }
}

package com.tcurrent.liverightnow.model;

import java.util.Objects;

public class StreamInfo
{
    private final Platform platform;
    private final String channelName;
    private final boolean live;
    private final String title;
    private final String category;
    private final int viewerCount;
    private final String sessionId;

    public StreamInfo(Platform platform, String channelName, boolean live, String title, String category, int viewerCount)
    {
        this(platform, channelName, live, title, category, viewerCount, "");
    }

    public StreamInfo(
        Platform platform,
        String channelName,
        boolean live,
        String title,
        String category,
        int viewerCount,
        String sessionId
    )
    {
        this.platform = platform;
        this.channelName = channelName;
        this.live = live;
        this.title = title != null ? title : "";
        this.category = category != null ? category : "";
        this.viewerCount = viewerCount;
        this.sessionId = sessionId != null ? sessionId : "";
    }

    public static StreamInfo offline(Platform platform, String channelName)
    {
        return new StreamInfo(platform, channelName, false, "", "", 0);
    }

    public Platform getPlatform()
    {
        return platform;
    }

    public String getChannelName()
    {
        return channelName;
    }

    public boolean isLive()
    {
        return live;
    }

    public String getTitle()
    {
        return title;
    }

    public String getCategory()
    {
        return category;
    }

    public int getViewerCount()
    {
        return viewerCount;
    }

    public String getSessionId()
    {
        return sessionId;
    }

    public String getStreamUrl()
    {
        return platform.getChannelUrl(channelName);
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        StreamInfo that = (StreamInfo) o;
        return live == that.live &&
                viewerCount == that.viewerCount &&
                platform == that.platform &&
                Objects.equals(channelName.toLowerCase(), that.channelName.toLowerCase()) &&
                Objects.equals(title, that.title) &&
                Objects.equals(category, that.category);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(platform, channelName.toLowerCase(), live, title, category, viewerCount);
    }
}

package com.tcurrent.liverightnow.notification;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.tcurrent.liverightnow.LiveRightNowConfig;
import com.tcurrent.liverightnow.model.Platform;
import com.tcurrent.liverightnow.model.StreamInfo;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;

@Singleton
public class StreamNotificationManager
{
    private final Client client;
    private final ClientThread clientThread;
    private final Notifier notifier;
    private final LiveRightNowConfig config;
    @Inject
    public StreamNotificationManager(
        Client client,
        ClientThread clientThread,
        Notifier notifier,
        LiveRightNowConfig config
    )
    {
        this.client = client;
        this.clientThread = clientThread;
        this.notifier = notifier;
        this.config = config;
    }

    public void notifyStreamerLive(StreamInfo stream)
    {
        notifyStreamersLive(List.of(stream));
    }

    public void notifyStreamersLive(List<StreamInfo> streams)
    {
        if (streams.isEmpty())
        {
            return;
        }

        List<MergedStream> merged = mergeByChannelName(streams);

        if (merged.size() == 1)
        {
            notifySingleStreamerLive(merged.get(0));
            return;
        }

        if (config.chatMessageEnabled())
        {
            sendInGameChat(merged);
        }

        if (config.notificationEnabled())
        {
            String names = formatStreamerNames(merged);
            notifier.notify(merged.size() + " tracked streamers are now live: " + names);
        }
    }

    // Combines entries for the same streamer so being live on Twitch and Kick at once
    // produces a single "X is now live on Twitch and Kick" message instead of two.
    private List<MergedStream> mergeByChannelName(List<StreamInfo> streams)
    {
        Map<String, MergedStream> merged = new LinkedHashMap<>();
        for (StreamInfo stream : streams)
        {
            String key = stream.getChannelName().toLowerCase();
            MergedStream existing = merged.get(key);
            if (existing == null)
            {
                merged.put(key, new MergedStream(stream.getChannelName(), stream.getPlatform().getDisplayName(), stream.getTitle()));
            }
            else
            {
                existing.platformNames.add(stream.getPlatform().getDisplayName());
            }
        }
        return new ArrayList<>(merged.values());
    }

    private void notifySingleStreamerLive(MergedStream stream)
    {
        String platformLabel = stream.platformLabel();

        if (config.chatMessageEnabled())
        {
            sendInGameMessage("[Live Right Now] " + stream.channelName + " is now live on " + platformLabel);
        }

        if (config.notificationEnabled())
        {
            notifier.notify(stream.channelName + " is now live on " + platformLabel);
        }
    }

    public void notifySessionExpired(Platform platform)
    {
        sendInGameMessage("[Live Right Now] Your " + platform.getDisplayName() + " session has expired. Please reconnect in the side panel.");
    }

    public void notifyConnectReminder(String messageText)
    {
        sendInGameMessage("[Live Right Now] " + messageText);
    }

    private void sendInGameChat(List<MergedStream> streams)
    {
        StringBuilder message = new StringBuilder("[Live Right Now] ")
            .append(streams.size()).append(" tracked streamers are now live: ");
        int displayed = Math.min(3, streams.size());
        for (int i = 0; i < displayed; i++)
        {
            if (i > 0)
            {
                message.append(", ");
            }
            message.append(streams.get(i).displayName());
        }

        int remaining = streams.size() - displayed;
        if (remaining > 0)
        {
            message.append(" and ").append(remaining).append(" more");
        }

        sendInGameMessage(message.toString());
    }

    private void sendInGameMessage(String message)
    {
        String prefix = "[Live Right Now] ";
        String body = message.startsWith(prefix) ? message.substring(prefix.length()) : message;
        String formattedMessage = "<col=00B4D8>" + prefix + "</col>" + body;
        clientThread.invokeLater(() -> client.addChatMessage(
            ChatMessageType.GAMEMESSAGE,
            "[Live Right Now]",
            formattedMessage,
            null,
            false
        ));
    }

    private String formatStreamerNames(List<MergedStream> streams)
    {
        String names = streams.stream()
            .limit(3)
            .map(MergedStream::displayName)
            .collect(Collectors.joining(", "));

        int remaining = streams.size() - 3;
        if (remaining > 0)
        {
            names += " and " + remaining + " more";
        }
        return names;
    }

    private static final class MergedStream
    {
        final String channelName;
        final List<String> platformNames;
        final String title;

        MergedStream(String channelName, String platformName, String title)
        {
            this.channelName = channelName;
            this.platformNames = new ArrayList<>();
            this.platformNames.add(platformName);
            this.title = title;
        }

        String platformLabel()
        {
            return String.join(" and ", platformNames);
        }

        String displayName()
        {
            return platformNames.size() > 1 ? channelName + " (" + platformLabel() + ")" : channelName;
        }
    }
}

package com.tcurrent.liverightnow.oauth;

import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;

import javax.inject.Inject;
import javax.inject.Singleton;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.tcurrent.liverightnow.LiveRightNowConfig;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Singleton
public class KickOAuthManager
{
    private static final Logger log = LoggerFactory.getLogger(KickOAuthManager.class);
    private static final String KICK_USERS_URL = "https://api.kick.com/public/v1/users";
    private static final String KICK_CHANNELS_URL = "https://api.kick.com/public/v1/channels";
    private static final String KICK_REVOKE_URL = "https://id.kick.com/oauth/revoke";
    private static final String KICK_AUTHORIZE_URL = "https://id.kick.com/oauth/authorize";
    private static final String KICK_REDIRECT_URI = "http://localhost:4646/callback";
    private static final String EXCHANGE_URL = "https://live-right-now-oauth-proxy.tcurrent.workers.dev/exchange";
    private static final String HANDOFF_URL = "https://live-right-now-oauth-proxy.tcurrent.workers.dev/handoff";
    private static final String REFRESH_URL = "https://live-right-now-oauth-proxy.tcurrent.workers.dev/refresh";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final LiveRightNowConfig config;
    private final ConfigManager configManager;
    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final ScheduledExecutorService executorService;
    private final OAuthLoopbackServer loopbackServer;
    private volatile String lastKnownToken;
    private volatile String lastKnownRefreshToken;

    @Inject
    public KickOAuthManager(
        LiveRightNowConfig config,
        ConfigManager configManager,
        OkHttpClient okHttpClient,
        Gson gson,
        ScheduledExecutorService executorService,
        OAuthLoopbackServer loopbackServer
    )
    {
        this.config = config;
        this.configManager = configManager;
        this.okHttpClient = okHttpClient;
        this.gson = gson;
        this.executorService = executorService;
        this.loopbackServer = loopbackServer;
        this.lastKnownToken = config.kickOAuthToken();
        this.lastKnownRefreshToken = config.kickRefreshToken();
    }

    public boolean isConnected()
    {
        String token = config.kickOAuthToken();
        boolean connected = token != null && !token.trim().isEmpty();
        if (connected)
        {
            lastKnownToken = token;
        }
        return connected;
    }

    public String getConnectedUser()
    {
        return config.kickConnectedUser();
    }

    public CompletableFuture<Boolean> startConnectFlow()
    {
        disconnect();
        CompletableFuture<Boolean> resultFuture = new CompletableFuture<>();
        OAuthFlow flow = OAuthFlow.create();

        try
        {
            loopbackServer.startKick(flow.getState(), (provider, authorizationCode) -> {
                if ("kick".equalsIgnoreCase(provider))
                {
                    executorService.execute(() -> {
                        String handoffCode = exchangeAuthorizationCode(
                            authorizationCode,
                            flow.getState(),
                            flow.getHandoffProof(),
                            flow.getCodeVerifier()
                        );
                        JsonObject tokens = handoffCode == null ? null : redeemHandoff(handoffCode, flow.getHandoffSecret());
                        if (tokens == null)
                        {
                            resultFuture.complete(false);
                            return;
                        }
                        String token = tokens.get("access_token").getAsString();
                        saveTokens(token, tokens);
                        fetchAndSaveKickUser(token);
                        resultFuture.complete(true);
                    });
                }
            });

            HttpUrl authorizeUrl = HttpUrl.parse(KICK_AUTHORIZE_URL).newBuilder()
                .addQueryParameter("response_type", "code")
                .addQueryParameter("client_id", config.kickClientId().trim())
                .addQueryParameter("redirect_uri", KICK_REDIRECT_URI)
                .addQueryParameter("scope", "user:read channel:read")
                .addQueryParameter("code_challenge", flow.getCodeChallenge())
                .addQueryParameter("code_challenge_method", "S256")
                .addQueryParameter("state", flow.getState())
                .build();
            LinkBrowser.browse(authorizeUrl.toString());
        }
        catch (IOException e)
        {
            log.error("Failed to start OAuth loopback server for Kick", e);
            resultFuture.complete(false);
        }

        return resultFuture;
    }

    public void disconnect()
    {
        String token = config.kickOAuthToken();
        String refreshToken = config.kickRefreshToken();
        lastKnownToken = null;
        lastKnownRefreshToken = null;
        configManager.unsetConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.KICK_REFRESH_TOKEN_KEY);
        configManager.unsetConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.KICK_OAUTH_TOKEN_KEY);
        configManager.unsetConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.KICK_CONNECTED_USER_KEY);
        revokeTokens(token, refreshToken);
    }

    public void handleConfigurationReset()
    {
        String token = lastKnownToken;
        String refreshToken = lastKnownRefreshToken;
        if (token == null || !config.kickOAuthToken().trim().isEmpty())
        {
            return;
        }

        lastKnownToken = null;
        lastKnownRefreshToken = null;
        revokeTokens(token, refreshToken);
    }

    private void revokeTokens(String token, String refreshToken)
    {
        if (token != null && !token.trim().isEmpty())
        {
            executorService.execute(() -> revokeToken(token, "access_token"));
        }
        if (refreshToken != null && !refreshToken.trim().isEmpty())
        {
            executorService.execute(() -> revokeToken(refreshToken, "refresh_token"));
        }
    }

    public void handleTokenExpired()
    {
        log.warn("Kick token has expired or is invalid. Disconnecting session.");
        disconnect();
    }

    /**
     * Returns the new access token, or null on failure. Disconnects only if Kick rejected the refresh token.
     */
    public synchronized String refreshAccessToken(String failedToken)
    {
        String current = config.kickOAuthToken();
        if (current != null && !current.trim().isEmpty() && !current.trim().equals(failedToken))
        {
            return current.trim();
        }

        String refreshToken = config.kickRefreshToken();
        if (refreshToken == null || refreshToken.trim().isEmpty())
        {
            handleTokenExpired();
            return null;
        }

        JsonObject payload = new JsonObject();
        payload.addProperty("provider", "kick");
        payload.addProperty("refresh_token", refreshToken.trim());
        RequestBody body = RequestBody.create(JSON, payload.toString());
        Request request = new Request.Builder().url(REFRESH_URL).post(body).build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            ResponseBody responseBody = response.body();
            JsonObject json = responseBody == null ? null : gson.fromJson(responseBody.charStream(), JsonObject.class);
            if (response.isSuccessful() && json != null && json.has("access_token"))
            {
                String token = json.get("access_token").getAsString();
                saveTokens(token, json);
                return token;
            }
            if (response.code() >= 400 && response.code() < 500)
            {
                handleTokenExpired();
            }
            else
            {
                log.warn("Kick token refresh failed with status {}", response.code());
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to refresh Kick token", e);
        }
        return null;
    }

    private void saveTokens(String token, JsonObject json)
    {
        lastKnownToken = token;
        if (json.has("refresh_token") && !json.get("refresh_token").isJsonNull())
        {
            String refreshToken = json.get("refresh_token").getAsString();
            lastKnownRefreshToken = refreshToken;
            configManager.setConfiguration(
                LiveRightNowConfig.GROUP,
                LiveRightNowConfig.KICK_REFRESH_TOKEN_KEY,
                refreshToken
            );
        }
        configManager.setConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.KICK_OAUTH_TOKEN_KEY, token);
    }

    private JsonObject redeemHandoff(String handoffCode, String handoffSecret)
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("handoff_code", handoffCode);
        payload.addProperty("handoff_secret", handoffSecret);
        RequestBody body = RequestBody.create(JSON, payload.toString());
        Request request = new Request.Builder().url(HANDOFF_URL).post(body).build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            ResponseBody responseBody = response.body();
            JsonObject json = responseBody == null ? null : gson.fromJson(responseBody.charStream(), JsonObject.class);
            if (response.isSuccessful() && json != null && json.has("access_token"))
            {
                return json;
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to redeem Kick OAuth handoff", e);
        }
        return null;
    }

    private String exchangeAuthorizationCode(String authorizationCode, String state, String handoffProof, String codeVerifier)
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("provider", "kick");
        payload.addProperty("code", authorizationCode);
        payload.addProperty("state", state);
        payload.addProperty("handoff_proof", handoffProof);
        payload.addProperty("code_verifier", codeVerifier);
        payload.addProperty("redirect_uri", KICK_REDIRECT_URI);
        RequestBody body = RequestBody.create(JSON, payload.toString());
        Request request = new Request.Builder().url(EXCHANGE_URL).post(body).build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            ResponseBody responseBody = response.body();
            JsonObject json = responseBody == null ? null : gson.fromJson(responseBody.charStream(), JsonObject.class);
            if (response.isSuccessful() && json != null && json.has("handoff_code"))
            {
                return json.get("handoff_code").getAsString();
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to exchange Kick authorization code", e);
        }
        return null;
    }

    private void revokeToken(String token, String tokenType)
    {
        HttpUrl baseUrl = HttpUrl.parse(KICK_REVOKE_URL);
        if (baseUrl == null)
        {
            return;
        }
        HttpUrl revokeUrl = baseUrl.newBuilder()
            .addQueryParameter("token", token.trim())
            .addQueryParameter("token_hint_type", tokenType)
            .build();
        RequestBody body = RequestBody.create(null, new byte[0]);
        Request request = new Request.Builder().url(revokeUrl).post(body).build();
        try (Response response = okHttpClient.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                log.warn("Kick token revocation returned status {}", response.code());
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to revoke Kick token", e);
        }
    }

    private void fetchAndSaveKickUser(String token)
    {
        Request request = new Request.Builder()
            .url(KICK_USERS_URL)
            .header("Authorization", "Bearer " + token)
            .header("Accept", "application/json")
            .get()
            .build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            ResponseBody body = response.body();
            JsonObject json = body == null ? null : gson.fromJson(body.charStream(), JsonObject.class);
            if (response.isSuccessful() && json != null && json.has("data"))
            {
                JsonElement dataElem = json.get("data");
                String username = extractUsername(dataElem);
                if (username != null && !username.isEmpty())
                {
                    configManager.setConfiguration(
                        LiveRightNowConfig.GROUP,
                        LiveRightNowConfig.KICK_CONNECTED_USER_KEY,
                        username
                    );
                    return;
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to fetch Kick user profile from users endpoint, trying channels endpoint", e);
        }

        Request channelRequest = new Request.Builder()
            .url(KICK_CHANNELS_URL)
            .header("Authorization", "Bearer " + token)
            .header("Accept", "application/json")
            .get()
            .build();

        try (Response response = okHttpClient.newCall(channelRequest).execute())
        {
            ResponseBody body = response.body();
            JsonObject json = body == null ? null : gson.fromJson(body.charStream(), JsonObject.class);
            if (response.isSuccessful() && json != null && json.has("data"))
            {
                JsonElement dataElem = json.get("data");
                String username = extractUsername(dataElem);
                if (username != null && !username.isEmpty())
                {
                    configManager.setConfiguration(
                        LiveRightNowConfig.GROUP,
                        LiveRightNowConfig.KICK_CONNECTED_USER_KEY,
                        username
                    );
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to fetch Kick user profile from channels endpoint", e);
        }
    }

    private String extractUsername(JsonElement dataElem)
    {
        if (dataElem.isJsonArray())
        {
            JsonArray arr = dataElem.getAsJsonArray();
            if (arr.size() > 0 && arr.get(0).isJsonObject())
            {
                JsonObject obj = arr.get(0).getAsJsonObject();
                if (obj.has("name") && !obj.get("name").isJsonNull())
                {
                    return obj.get("name").getAsString();
                }
                if (obj.has("username") && !obj.get("username").isJsonNull())
                {
                    return obj.get("username").getAsString();
                }
                if (obj.has("slug") && !obj.get("slug").isJsonNull())
                {
                    return obj.get("slug").getAsString();
                }
            }
        }
        else if (dataElem.isJsonObject())
        {
            JsonObject obj = dataElem.getAsJsonObject();
            if (obj.has("name") && !obj.get("name").isJsonNull())
            {
                return obj.get("name").getAsString();
            }
            if (obj.has("username") && !obj.get("username").isJsonNull())
            {
                return obj.get("username").getAsString();
            }
            if (obj.has("slug") && !obj.get("slug").isJsonNull())
            {
                return obj.get("slug").getAsString();
            }
        }
        return null;
    }
}

package com.tcurrent.liverightnow.oauth;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

final class OAuthFlow
{
    private static final SecureRandom SECURE_RANDOM = new SecureRandom();

    private final String state;
    private final String handoffSecret;
    private final String handoffProof;
    private final String codeVerifier;
    private final String codeChallenge;

    private OAuthFlow(String state, String handoffSecret, String handoffProof, String codeVerifier, String codeChallenge)
    {
        this.state = state;
        this.handoffSecret = handoffSecret;
        this.handoffProof = handoffProof;
        this.codeVerifier = codeVerifier;
        this.codeChallenge = codeChallenge;
    }

    static OAuthFlow create()
    {
        String state = randomValue();
        String handoffSecret = randomValue();
        String codeVerifier = randomValue();
        return new OAuthFlow(
            state,
            handoffSecret,
            sha256Base64Url(handoffSecret),
            codeVerifier,
            sha256Base64Url(codeVerifier)
        );
    }

    String getState()
    {
        return state;
    }

    String getHandoffSecret()
    {
        return handoffSecret;
    }

    String getHandoffProof()
    {
        return handoffProof;
    }

    String getCodeVerifier()
    {
        return codeVerifier;
    }

    String getCodeChallenge()
    {
        return codeChallenge;
    }

    private static String randomValue()
    {
        byte[] bytes = new byte[32];
        SECURE_RANDOM.nextBytes(bytes);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }

    private static String sha256Base64Url(String value)
    {
        try
        {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);
        }
        catch (NoSuchAlgorithmException e)
        {
            throw new IllegalStateException("SHA-256 is unavailable", e);
        }
    }
}

package com.tcurrent.liverightnow.oauth;

import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.BiConsumer;

import javax.inject.Inject;
import javax.inject.Singleton;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;

@Singleton
public class OAuthLoopbackServer
{
    private static final Logger log = LoggerFactory.getLogger(OAuthLoopbackServer.class);
    public static final int PORT = 4646;
    private static final String CALLBACK_PATH = "/callback";
    private static final long FLOW_TIMEOUT_MINUTES = 5;

    private final ScheduledExecutorService executorService;
    private HttpServer server;
    private BiConsumer<String, String> handoffCallback;
    private String expectedProvider;
    private String expectedState;
    private boolean callbackConsumed;
    private boolean authorizationCodeCallback;
    private boolean implicitTokenCallback;

    @Inject
    public OAuthLoopbackServer(ScheduledExecutorService executorService)
    {
        this.executorService = executorService;
    }

    public synchronized void start(String provider, String state, BiConsumer<String, String> callback) throws IOException
    {
        startInternal(provider, state, callback, false, false);
    }

    public synchronized void startTwitch(String state, BiConsumer<String, String> callback) throws IOException
    {
        startInternal("twitch", state, callback, false, true);
    }

    public synchronized void startKick(String state, BiConsumer<String, String> callback) throws IOException
    {
        startInternal("kick", state, callback, true, false);
    }

    private void startInternal(String provider, String state, BiConsumer<String, String> callback, boolean authorizationCodeCallback, boolean implicitTokenCallback) throws IOException
    {
        stop();

        this.handoffCallback = callback;
        this.expectedProvider = provider;
        this.expectedState = state;
        this.callbackConsumed = false;
        this.authorizationCodeCallback = authorizationCodeCallback;
        this.implicitTokenCallback = implicitTokenCallback;

        server = HttpServer.create(new InetSocketAddress("localhost", PORT), 0);
        server.createContext(CALLBACK_PATH, new CallbackHandler());
        server.setExecutor(executorService);
        server.start();
        log.debug("OAuth loopback server started on port {}", PORT);
        executorService.schedule(() -> stopIfState(state), FLOW_TIMEOUT_MINUTES, TimeUnit.MINUTES);
    }

    public synchronized void stop()
    {
        if (server != null)
        {
            server.stop(0);
            server = null;
            handoffCallback = null;
            expectedProvider = null;
            expectedState = null;
            callbackConsumed = false;
            authorizationCodeCallback = false;
            implicitTokenCallback = false;
            log.debug("OAuth loopback server stopped");
        }
    }

    private synchronized void stopIfState(String state)
    {
        if (state.equals(expectedState))
        {
            stop();
        }
    }

    private class CallbackHandler implements HttpHandler
    {
        @Override
        public void handle(HttpExchange exchange) throws IOException
        {
            String requestPath = exchange.getRequestURI().getPath();
            boolean implicitTokenPost = implicitTokenCallback
                && "POST".equalsIgnoreCase(exchange.getRequestMethod())
                && (CALLBACK_PATH + "/token").equals(requestPath);

            if (implicitTokenCallback && "GET".equalsIgnoreCase(exchange.getRequestMethod())
                && CALLBACK_PATH.equals(requestPath))
            {
                sendHtml(exchange, implicitCallbackPage(), 200);
                return;
            }

            String requestData = implicitTokenPost
                ? new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8)
                : exchange.getRequestURI().getQuery();
            Map<String, String> params = parseQuery(requestData);

            String provider = params.get("provider");
            String handoffCode = params.get("handoff_code");
            String authorizationCode = params.get("code");
            String accessToken = params.get("access_token");
            String state = params.get("state");
            String oauthError = params.get("error");

            if (implicitTokenPost)
            {
                provider = "twitch";
            }

            String responseHtml;
            int statusCode;
            boolean accepted = false;
            BiConsumer<String, String> callback = null;

            synchronized (OAuthLoopbackServer.this)
            {
                if (provider == null && authorizationCodeCallback)
                {
                    provider = expectedProvider;
                }

                boolean flowValid = expectedState != null && expectedState.equals(state)
                    && expectedProvider != null && expectedProvider.equalsIgnoreCase(provider)
                    && !callbackConsumed
                    && (!implicitTokenPost || "http://localhost:4646".equals(exchange.getRequestHeaders().getFirst("Origin")));

                if (!flowValid)
                {
                    responseHtml = errorPage("This authorization link is invalid or has expired. Please click Connect again in RuneLite.");
                    statusCode = 400;
                }
                else if (implicitTokenPost && oauthError != null && !oauthError.trim().isEmpty())
                {
                    responseHtml = errorPage("Twitch authorization was not completed. Please return to RuneLite and try again.");
                    statusCode = 400;
                    accepted = true;
                    callback = handoffCallback;
                }
                else if (implicitTokenPost && accessToken != null && !accessToken.trim().isEmpty())
                {
                    responseHtml = successPage("Twitch authorization received. You can safely close this window and return to RuneLite.");
                    statusCode = 200;
                    accepted = true;
                    callback = handoffCallback;
                }
                else if (authorizationCodeCallback && authorizationCode != null && !authorizationCode.trim().isEmpty())
                {
                    String platformDisplay = "kick".equalsIgnoreCase(provider) ? "Kick" : "Twitch";
                    responseHtml = successPage(platformDisplay + " authorization received. You can safely close this window and return to RuneLite.");
                    statusCode = 200;
                    accepted = true;
                    callback = handoffCallback;
                }
                else if (!authorizationCodeCallback && handoffCode != null && !handoffCode.trim().isEmpty())
                {
                    String platformDisplay = "kick".equalsIgnoreCase(provider) ? "Kick" : "Twitch";
                    responseHtml = successPage(platformDisplay + " connected successfully! You can safely close this window and return to RuneLite.");
                    statusCode = 200;
                    accepted = true;
                    callback = handoffCallback;
                }
                else
                {
                    responseHtml = errorPage("Authorization failed or the secure handoff code is missing.");
                    statusCode = 400;
                }

                if (accepted)
                {
                    callbackConsumed = true;
                }
            }

            byte[] bytes = responseHtml.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "text/html; charset=utf-8");
            exchange.getResponseHeaders().set("Cache-Control", "no-store");
            exchange.getResponseHeaders().set("Referrer-Policy", "no-referrer");
            exchange.sendResponseHeaders(statusCode, bytes.length);
            try (OutputStream os = exchange.getResponseBody())
            {
                os.write(bytes);
            }

            if (accepted && callback != null)
            {
                String callbackValue = implicitTokenCallback
                    ? (oauthError == null || oauthError.trim().isEmpty() ? accessToken : null)
                    : (authorizationCodeCallback ? authorizationCode : handoffCode);
                callback.accept(provider.toLowerCase(), callbackValue);
            }

            executorService.schedule(() -> stopIfState(state), 2, TimeUnit.SECONDS);
        }
    }

    private void sendHtml(HttpExchange exchange, String html, int statusCode) throws IOException
    {
        byte[] bytes = html.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "text/html; charset=utf-8");
        exchange.getResponseHeaders().set("Cache-Control", "no-store");
        exchange.getResponseHeaders().set("Referrer-Policy", "no-referrer");
        exchange.getResponseHeaders().set("X-Content-Type-Options", "nosniff");
        exchange.getResponseHeaders().set("Content-Security-Policy", "default-src 'none'; script-src 'unsafe-inline'; connect-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'");
        exchange.sendResponseHeaders(statusCode, bytes.length);
        try (OutputStream output = exchange.getResponseBody())
        {
            output.write(bytes);
        }
    }

    private String implicitCallbackPage()
    {
        return "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Live Right Now - Twitch Authorization</title>"
            + "<style>body{font-family:Segoe UI,Helvetica,Arial,sans-serif;background:#121212;color:#eee;display:flex;justify-content:center;align-items:center;height:100vh;margin:0;}"
            + ".card{background:#1e1e1e;padding:30px 40px;border-radius:10px;border:1px solid #333;text-align:center;box-shadow:0 4px 20px rgba(0,0,0,0.5);max-width:400px;}"
            + "h2{color:#00B4D8;margin-top:0;}p{color:#aaa;line-height:1.5;}</style></head>"
            + "<body><div class='card'><h2>Live Right Now</h2><p id='status'>Completing Twitch authorization...</p></div><script>"
            + "const fragment=new URLSearchParams(window.location.hash.slice(1));const query=new URLSearchParams(window.location.search);"
            + "const token=fragment.get('access_token')||'';const state=fragment.get('state')||query.get('state')||'';"
            + "const error=fragment.get('error')||query.get('error')||'';"
            + "history.replaceState(null,'',window.location.pathname);"
            + "if(!state||(!token&&!error)){document.getElementById('status').textContent='Authorization response was incomplete. Return to RuneLite and try again.';}"
            + "else{fetch('/callback/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},"
            + "body:new URLSearchParams({state:state,access_token:token,error:error}),cache:'no-store'})"
            + ".then(response=>{if(!response.ok)throw new Error();document.getElementById('status').textContent='Twitch authorization received. You can safely close this window and return to RuneLite.';})"
            + ".catch(()=>{document.getElementById('status').textContent='Authorization could not be completed. Return to RuneLite and try again.';});}"
            + "</script></body></html>";
    }

    private String successPage(String message)
    {
        return "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Live Right Now - Connected</title>"
            + "<style>body{font-family:Segoe UI,Helvetica,Arial,sans-serif;background:#121212;color:#eee;display:flex;justify-content:center;align-items:center;height:100vh;margin:0;}"
            + ".card{background:#1e1e1e;padding:30px 40px;border-radius:10px;border:1px solid #333;text-align:center;box-shadow:0 4px 20px rgba(0,0,0,0.5);max-width:400px;}"
            + "h2{color:#00B4D8;margin-top:0;}p{color:#aaa;line-height:1.5;}</style></head>"
            + "<body><div class='card'><h2>Live Right Now</h2><p>" + message + "</p></div></body></html>";
    }

    private String errorPage(String message)
    {
        return "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Live Right Now - Error</title>"
            + "<style>body{font-family:Segoe UI,Helvetica,Arial,sans-serif;background:#121212;color:#eee;display:flex;justify-content:center;align-items:center;height:100vh;margin:0;}"
            + ".card{background:#1e1e1e;padding:30px 40px;border-radius:10px;border:1px solid #ff4444;text-align:center;max-width:400px;}"
            + "h2{color:#ff4444;margin-top:0;}p{color:#aaa;}</style></head>"
            + "<body><div class='card'><h2>Authentication Error</h2>"
            + "<p>" + message + "</p></div></body></html>";
    }

    private Map<String, String> parseQuery(String query)
    {
        Map<String, String> map = new HashMap<>();
        if (query == null || query.isEmpty())
        {
            return map;
        }

        for (String param : query.split("&"))
        {
            String[] pair = param.split("=", 2);
            if (pair.length == 2)
            {
                try
                {
                    String key = java.net.URLDecoder.decode(pair[0], StandardCharsets.UTF_8.name());
                    String value = java.net.URLDecoder.decode(pair[1], StandardCharsets.UTF_8.name());
                    map.put(key, value);
                }
                catch (java.io.UnsupportedEncodingException | IllegalArgumentException ignored)
                {
                }
            }
        }
        return map;
    }
}

package com.tcurrent.liverightnow.oauth;

import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;

import javax.inject.Inject;
import javax.inject.Singleton;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.tcurrent.liverightnow.LiveRightNowConfig;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;
import okhttp3.FormBody;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Singleton
public class TwitchOAuthManager
{
    private static final Logger log = LoggerFactory.getLogger(TwitchOAuthManager.class);
    private static final String TWITCH_VALIDATE_URL = "https://id.twitch.tv/oauth2/validate";
    private static final String TWITCH_REVOKE_URL = "https://id.twitch.tv/oauth2/revoke";
    private static final String TWITCH_AUTHORIZE_URL = "https://id.twitch.tv/oauth2/authorize";
    private static final String TWITCH_REDIRECT_URI = "http://localhost:4646/callback";

    private final LiveRightNowConfig config;
    private final ConfigManager configManager;
    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final ScheduledExecutorService executorService;
    private final OAuthLoopbackServer loopbackServer;
    private volatile String lastKnownToken;

    @Inject
    public TwitchOAuthManager(
        LiveRightNowConfig config,
        ConfigManager configManager,
        OkHttpClient okHttpClient,
        Gson gson,
        ScheduledExecutorService executorService,
        OAuthLoopbackServer loopbackServer
    )
    {
        this.config = config;
        this.configManager = configManager;
        this.okHttpClient = okHttpClient;
        this.gson = gson;
        this.executorService = executorService;
        this.loopbackServer = loopbackServer;
        this.lastKnownToken = config.twitchOAuthToken();
    }

    public boolean isConnected()
    {
        String token = config.twitchOAuthToken();
        boolean connected = token != null && !token.trim().isEmpty();
        if (connected)
        {
            lastKnownToken = token;
        }
        return connected;
    }

    public String getConnectedUser()
    {
        return config.twitchConnectedUser();
    }

    public CompletableFuture<Boolean> startConnectFlow()
    {
        disconnect();
        CompletableFuture<Boolean> resultFuture = new CompletableFuture<>();
        OAuthFlow flow = OAuthFlow.create();

        try
        {
            loopbackServer.startTwitch(flow.getState(), (provider, token) -> {
                if ("twitch".equalsIgnoreCase(provider))
                {
                    executorService.execute(() -> {
                        if (token == null)
                        {
                            resultFuture.complete(false);
                            return;
                        }
                        saveToken(token);
                        fetchAndSaveTwitchUser(token);
                        resultFuture.complete(true);
                    });
                }
            });

            HttpUrl authorizeUrl = HttpUrl.parse(TWITCH_AUTHORIZE_URL).newBuilder()
                .addQueryParameter("response_type", "token")
                .addQueryParameter("client_id", config.twitchClientId().trim())
                .addQueryParameter("redirect_uri", TWITCH_REDIRECT_URI)
                .addQueryParameter("scope", "")
                .addQueryParameter("state", flow.getState())
                .build();
            LinkBrowser.browse(authorizeUrl.toString());
        }
        catch (IOException e)
        {
            log.error("Failed to start OAuth loopback server for Twitch", e);
            resultFuture.complete(false);
        }

        return resultFuture;
    }

    public void disconnect()
    {
        String token = config.twitchOAuthToken();
        lastKnownToken = null;
        configManager.unsetConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.TWITCH_OAUTH_TOKEN_KEY);
        configManager.unsetConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.TWITCH_CONNECTED_USER_KEY);
        if (token != null && !token.trim().isEmpty())
        {
            executorService.execute(() -> revokeToken(token));
        }
    }

    public void handleConfigurationReset()
    {
        String token = lastKnownToken;
        if (token == null || !config.twitchOAuthToken().trim().isEmpty())
        {
            return;
        }

        lastKnownToken = null;
        executorService.execute(() -> revokeToken(token));
    }

    public void handleTokenExpired()
    {
        log.warn("Twitch token has expired or is invalid. Disconnecting session.");
        disconnect();
    }

    private void saveToken(String token)
    {
        lastKnownToken = token;
        configManager.setConfiguration(LiveRightNowConfig.GROUP, LiveRightNowConfig.TWITCH_OAUTH_TOKEN_KEY, token);
    }

    private void revokeToken(String token)
    {
        RequestBody body = new FormBody.Builder()
            .add("client_id", config.twitchClientId().trim())
            .add("token", token.trim())
            .build();
        Request request = new Request.Builder().url(TWITCH_REVOKE_URL).post(body).build();
        try (Response response = okHttpClient.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                log.warn("Twitch token revocation returned status {}", response.code());
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to revoke Twitch token", e);
        }
    }

    private void fetchAndSaveTwitchUser(String token)
    {
        Request request = new Request.Builder()
            .url(TWITCH_VALIDATE_URL)
            .header("Authorization", "OAuth " + token)
            .get()
            .build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            ResponseBody body = response.body();
            JsonObject json = body == null ? null : gson.fromJson(body.charStream(), JsonObject.class);
            if (response.isSuccessful() && json != null && json.has("login"))
            {
                configManager.setConfiguration(
                    LiveRightNowConfig.GROUP,
                    LiveRightNowConfig.TWITCH_CONNECTED_USER_KEY,
                    json.get("login").getAsString()
                );
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to validate Twitch token", e);
        }
    }
}

package com.tcurrent.liverightnow.service;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import javax.inject.Inject;
import javax.inject.Singleton;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.tcurrent.liverightnow.LiveRightNowConfig;
import com.tcurrent.liverightnow.model.Platform;
import com.tcurrent.liverightnow.model.StreamInfo;
import com.tcurrent.liverightnow.notification.StreamNotificationManager;
import com.tcurrent.liverightnow.oauth.KickOAuthManager;

import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Singleton
public class KickService
{
    private static final Logger log = LoggerFactory.getLogger(KickService.class);
    private static final String KICK_CHANNELS_API_URL = "https://api.kick.com/public/v1/channels";

    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final LiveRightNowConfig config;
    private final KickOAuthManager kickOAuthManager;
    private final StreamNotificationManager notificationManager;

    // Kick's public channels endpoint keys live status off broadcaster_user_id;
    // slugs are only usable for the initial lookup, so cache the resolved id per username.
    private final Map<String, Long> resolvedBroadcasterIds = new ConcurrentHashMap<>();

    @Inject
    public KickService(
        OkHttpClient okHttpClient,
        Gson gson,
        LiveRightNowConfig config,
        KickOAuthManager kickOAuthManager,
        StreamNotificationManager notificationManager
    )
    {
        this.okHttpClient = okHttpClient;
        this.gson = gson;
        this.config = config;
        this.kickOAuthManager = kickOAuthManager;
        this.notificationManager = notificationManager;
    }

    public List<StreamInfo> fetchStreams(List<String> usernames)
    {
        if (usernames == null || usernames.isEmpty())
        {
            return Collections.emptyList();
        }

        if (currentToken().isEmpty())
        {
            log.warn("Kick OAuth Token is not configured. Skipping Kick lookup.");
            return Collections.emptyList();
        }

        List<String> normalizedUsers = new ArrayList<>();
        for (String user : usernames)
        {
            String trimmed = user.trim().toLowerCase();
            if (!trimmed.isEmpty())
            {
                normalizedUsers.add(trimmed);
            }
        }

        if (normalizedUsers.isEmpty())
        {
            return Collections.emptyList();
        }

        List<String> unresolved = new ArrayList<>();
        List<Long> resolvedIds = new ArrayList<>();
        for (String user : normalizedUsers)
        {
            Long id = resolvedBroadcasterIds.get(user);
            if (id != null)
            {
                resolvedIds.add(id);
            }
            else
            {
                unresolved.add(user);
            }
        }

        // Kick's channels endpoint disallows mixing slug and broadcaster_user_id in a single request.
        Map<String, JsonObject> channelsByUsername = new HashMap<>();
        if (!unresolved.isEmpty())
        {
            List<JsonObject> channels = requestChannels("slug", unresolved);
            if (channels == null)
            {
                return Collections.emptyList();
            }
            for (JsonObject channelObj : channels)
            {
                String slug = getString(channelObj, "slug");
                if (slug.isEmpty())
                {
                    continue;
                }
                Long id = getLong(channelObj, "broadcaster_user_id");
                if (id != null)
                {
                    resolvedBroadcasterIds.put(slug.toLowerCase(), id);
                }
                channelsByUsername.put(slug.toLowerCase(), channelObj);
            }
        }

        if (!resolvedIds.isEmpty())
        {
            List<String> idStrings = new ArrayList<>();
            for (Long id : resolvedIds)
            {
                idStrings.add(String.valueOf(id));
            }
            List<JsonObject> channels = requestChannels("broadcaster_user_id", idStrings);
            if (channels == null)
            {
                return Collections.emptyList();
            }
            for (JsonObject channelObj : channels)
            {
                String slug = getString(channelObj, "slug");
                if (!slug.isEmpty())
                {
                    channelsByUsername.put(slug.toLowerCase(), channelObj);
                }
            }
        }

        List<StreamInfo> results = new ArrayList<>();
        for (String user : usernames)
        {
            String lower = user.trim().toLowerCase();
            if (lower.isEmpty())
            {
                continue;
            }

            JsonObject channelObj = channelsByUsername.get(lower);
            results.add(channelObj != null
                ? parseChannel(user.trim(), channelObj)
                : StreamInfo.offline(Platform.KICK, user.trim()));
        }

        return results;
    }

    /**
     * Returns null on a request failure (401/unsuccessful/IO error) so callers can bail out entirely.
     */
    private List<JsonObject> requestChannels(String paramName, List<String> values)
    {
        return requestChannels(paramName, values, currentToken(), true);
    }

    private String currentToken()
    {
        String token = config.kickOAuthToken() != null ? config.kickOAuthToken().trim() : "";
        return token.toLowerCase().startsWith("bearer ") ? token.substring(7).trim() : token;
    }

    private List<JsonObject> requestChannels(String paramName, List<String> values, String token, boolean canRefresh)
    {
        HttpUrl baseUrl = HttpUrl.parse(KICK_CHANNELS_API_URL);
        if (baseUrl == null)
        {
            return null;
        }

        HttpUrl.Builder urlBuilder = baseUrl.newBuilder();
        for (String value : values)
        {
            urlBuilder.addQueryParameter(paramName, value);
        }

        Request request = new Request.Builder()
            .url(urlBuilder.build())
            .header("Authorization", "Bearer " + token)
            .header("Accept", "application/json")
            .get()
            .build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            if (response.code() == 401)
            {
                log.warn("Kick API returned 401 Unauthorized (OAuth token expired).");
                String refreshed = canRefresh ? kickOAuthManager.refreshAccessToken(token) : null;
                if (refreshed != null)
                {
                    return requestChannels(paramName, values, refreshed, false);
                }
                if (!kickOAuthManager.isConnected())
                {
                    notificationManager.notifySessionExpired(Platform.KICK);
                }
                return null;
            }

            if (!response.isSuccessful())
            {
                log.warn("Kick API returned unsuccessful response code: {}", response.code());
                return null;
            }

            ResponseBody body = response.body();
            if (body == null)
            {
                return Collections.emptyList();
            }

            JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
            if (json == null || !json.has("data") || !json.get("data").isJsonArray())
            {
                return Collections.emptyList();
            }

            List<JsonObject> channels = new ArrayList<>();
            for (JsonElement element : json.getAsJsonArray("data"))
            {
                if (element.isJsonObject())
                {
                    channels.add(element.getAsJsonObject());
                }
            }
            return channels;
        }
        catch (IOException | RuntimeException e)
        {
            log.error("Failed to query Kick channels", e);
            return null;
        }
    }

    private StreamInfo parseChannel(String displayName, JsonObject channelObj)
    {
        String title = getString(channelObj, "stream_title");
        String category = "";
        boolean isLive = false;
        int viewerCount = 0;
        String sessionId = "";

        if (channelObj.has("category") && channelObj.get("category").isJsonObject())
        {
            category = getString(channelObj.getAsJsonObject("category"), "name");
        }

        if (channelObj.has("stream") && channelObj.get("stream").isJsonObject())
        {
            JsonObject stream = channelObj.getAsJsonObject("stream");
            isLive = stream.has("is_live") && !stream.get("is_live").isJsonNull() && stream.get("is_live").getAsBoolean();
            if (stream.has("viewer_count") && !stream.get("viewer_count").isJsonNull())
            {
                viewerCount = stream.get("viewer_count").getAsInt();
            }
            sessionId = getString(stream, "start_time");
        }

        return new StreamInfo(Platform.KICK, displayName, isLive, title, category, viewerCount, sessionId);
    }

    private String getString(JsonObject obj, String key)
    {
        return obj.has(key) && !obj.get(key).isJsonNull() ? obj.get(key).getAsString() : "";
    }

    private Long getLong(JsonObject obj, String key)
    {
        return obj.has(key) && !obj.get(key).isJsonNull() ? obj.get(key).getAsLong() : null;
    }
}

package com.tcurrent.liverightnow.service;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import javax.inject.Inject;
import javax.inject.Singleton;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.tcurrent.liverightnow.LiveRightNowConfig;
import com.tcurrent.liverightnow.model.Platform;
import com.tcurrent.liverightnow.model.StreamInfo;
import com.tcurrent.liverightnow.notification.StreamNotificationManager;
import com.tcurrent.liverightnow.oauth.TwitchOAuthManager;

import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Singleton
public class TwitchService
{
    private static final Logger log = LoggerFactory.getLogger(TwitchService.class);
    private static final String HELIX_STREAMS_URL = "https://api.twitch.tv/helix/streams";

    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final LiveRightNowConfig config;
    private final TwitchOAuthManager twitchOAuthManager;
    private final StreamNotificationManager notificationManager;

    @Inject
    public TwitchService(
        OkHttpClient okHttpClient,
        Gson gson,
        LiveRightNowConfig config,
        TwitchOAuthManager twitchOAuthManager,
        StreamNotificationManager notificationManager
    )
    {
        this.okHttpClient = okHttpClient;
        this.gson = gson;
        this.config = config;
        this.twitchOAuthManager = twitchOAuthManager;
        this.notificationManager = notificationManager;
    }

    public List<StreamInfo> fetchStreams(List<String> usernames)
    {
        if (usernames == null || usernames.isEmpty())
        {
            return Collections.emptyList();
        }

        String clientId = config.twitchClientId() != null ? config.twitchClientId().trim() : "";
        String token = config.twitchOAuthToken() != null ? config.twitchOAuthToken().trim() : "";

        if (clientId.isEmpty() || token.isEmpty())
        {
            log.warn("Twitch Client ID or OAuth Token is not configured. Skipping Twitch lookup.");
            return Collections.emptyList();
        }

        // Strip "Bearer " prefix if user included it in config
        if (token.toLowerCase().startsWith("bearer "))
        {
            token = token.substring(7).trim();
        }

        HttpUrl baseUrl = HttpUrl.parse(HELIX_STREAMS_URL);
        if (baseUrl == null)
        {
            return Collections.emptyList();
        }

        HttpUrl.Builder urlBuilder = baseUrl.newBuilder();
        for (String user : usernames)
        {
            String trimmed = user.trim().toLowerCase();
            if (!trimmed.isEmpty())
            {
                urlBuilder.addQueryParameter("user_login", trimmed);
            }
        }

        Request request = new Request.Builder()
            .url(urlBuilder.build())
            .header("Client-Id", clientId)
            .header("Authorization", "Bearer " + token)
            .get()
            .build();

        try (Response response = okHttpClient.newCall(request).execute())
        {
            if (response.code() == 401)
            {
                log.warn("Twitch API returned 401 Unauthorized (OAuth token expired).");
                twitchOAuthManager.handleTokenExpired();
                notificationManager.notifySessionExpired(Platform.TWITCH);
                return Collections.emptyList();
            }

            if (!response.isSuccessful())
            {
                log.warn("Twitch API returned unsuccessful response code: {}", response.code());
                return Collections.emptyList();
            }

            ResponseBody body = response.body();
            if (body == null)
            {
                return Collections.emptyList();
            }

            JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
            if (json == null || !json.has("data"))
            {
                return Collections.emptyList();
            }

            Map<String, StreamInfo> liveMap = new HashMap<>();
            JsonArray dataArray = json.getAsJsonArray("data");
            for (JsonElement element : dataArray)
            {
                if (!element.isJsonObject())
                {
                    continue;
                }

                JsonObject streamObj = element.getAsJsonObject();
                String login = streamObj.has("user_login") ? streamObj.get("user_login").getAsString() : "";
                String type = streamObj.has("type") ? streamObj.get("type").getAsString() : "";
                boolean isLive = "live".equalsIgnoreCase(type);
                String title = streamObj.has("title") ? streamObj.get("title").getAsString() : "";
                String gameName = streamObj.has("game_name") ? streamObj.get("game_name").getAsString() : "";
                int viewerCount = streamObj.has("viewer_count") ? streamObj.get("viewer_count").getAsInt() : 0;
                String streamId = streamObj.has("id") ? streamObj.get("id").getAsString() : "";

                if (!login.isEmpty())
                {
                    liveMap.put(login.toLowerCase(), new StreamInfo(Platform.TWITCH, login, isLive, title, gameName, viewerCount, streamId));
                }
            }

            List<StreamInfo> results = new ArrayList<>();
            for (String user : usernames)
            {
                String lower = user.trim().toLowerCase();
                if (lower.isEmpty())
                {
                    continue;
                }

                StreamInfo stream = liveMap.get(lower);
                if (stream != null)
                {
                    results.add(new StreamInfo(
                        Platform.TWITCH,
                        user.trim(),
                        stream.isLive(),
                        stream.getTitle(),
                        stream.getCategory(),
                        stream.getViewerCount(),
                        stream.getSessionId()
                    ));
                }
                else
                {
                    results.add(StreamInfo.offline(Platform.TWITCH, user.trim()));
                }
            }

            return results;
        }
        catch (IOException | RuntimeException e)
        {
            log.error("Failed to query Twitch streams", e);
            return Collections.emptyList();
        }
    }
}

package com.tcurrent.liverightnow.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagConstraints;
